TRANSLATIONS = {lang: {key: row[index] for key,row in ROWS.items()} for index,lang in enumerate(LANGUAGES)}
def translate(key, lang='ru', **kwargs):
    text = TRANSLATIONS.get(lang, TRANSLATIONS['ru']).get(key, TRANSLATIONS['ru'].get(key, key))
    try: return text.format(**kwargs)
    except (KeyError, ValueError): return text
def t(key, lang='ru', **kwargs): return translate(key, lang, **kwargs)
